  "output_head": ":root {
  --color-canvas: white;
  --color-ink: oklch(26% 0.05 264);
  --color-accent: oklch(57.02% 0.1895 260.46);

  --text-large: 6rem;
  --text-medium: 2rem;
  --text-normal: 1rem;

  @media (prefers-color-scheme: dark) {
    --color-canvas: oklch(20% 0.0195 232.58);
